export const REQUEST_AUTH = 'REQUEST_AUTH'
export const RECEIVE_AUTH = 'RECEIVE_AUTH'
export const REQUEST_AUTH_FAILURE = 'REQUEST_AUTH_FAILURE'

export const fetchAuthFailure = error => ({

  type: REQUEST_AUTH_FAILURE,
  payload: { error }
});

export function requestAuth() {
  return {
    type: REQUEST_AUTH
  }
}

export function receiveAuth(json) {
  //console.log('receive auth:');
  return {
    type: RECEIVE_AUTH,
    authResult: json.authResult,
    receivedAt: Date.now()
  }
}

export function fetchAuth() {
  //console.log('fetch auth');
  return dispatch => {
    dispatch(requestAuth())
    return fetch('https://scbm.amfdev.co.uk/api/auths/', {
      method: "GET",
      headers: {
        'Accept': 'application/json',
        'Content-Type': 'application/json',
        'Cache': 'no-cache'
      },
      credentials: 'include'
      })
      .then(handleErrors)
      .then(response => response.json())
      .then(json => dispatch(receiveAuth(json)))
      .catch(error => dispatch(fetchAuthFailure(error)));
  }
}


function handleErrors(response) {
  console.log(response);
  if (!response.ok) {
    throw Error(response.statusText);
  }
  return response;
}
